import type { Metadata, Viewport } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import { Suspense } from "react";
import { AvisoSemAcesso, Toaster } from "@/components/action-form";
import { LuzNoBotao } from "@/components/luz-no-botao";
import { MascaraCampos } from "@/components/mascara-campos";
import { Confirmador } from "@/components/confirm-dialog";
import { NavProgress } from "@/components/nav-progress";
import { AreaTransition } from "@/components/area-transition";
import { scriptTema } from "@/lib/tema";
import "./globals.css";

const geist = Geist({ variable: "--font-geist", subsets: ["latin"] });
const geistMono = Geist_Mono({ variable: "--font-geist-mono", subsets: ["latin"] });

export const metadata: Metadata = {
  metadataBase: new URL(process.env.APP_URL || "http://localhost:3000"),
  title: { default: "depo", template: "%s · depo" },
  description: "Gestão de pedidos, entregas, estoque de retornáveis e acerto de caixa para distribuidoras de água e gás.",
  applicationName: "depo",
};

export const viewport: Viewport = {
  themeColor: [
    { media: "(prefers-color-scheme: light)", color: "#fafafa" },
    { media: "(prefers-color-scheme: dark)", color: "#0a0a0a" },
  ],
  // sem isto o iPhone devolve 0 em env(safe-area-inset-*) e as barras de baixo encostam na barra de gestos
  viewportFit: "cover",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    // suppressHydrationWarning: o script abaixo põe data-tema no <html> antes do React chegar
    // data-scroll-behavior: a rolagem suave vale para os atalhos dentro da página; nas trocas de tela o Next desliga
    <html lang="pt-BR" className={`${geist.variable} ${geistMono.variable} h-full`} data-scroll-behavior="smooth" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: scriptTema }} />
      </head>
      <body className="min-h-full">
        <Suspense fallback={null}>
          <NavProgress />
        </Suspense>
        <AreaTransition>{children}</AreaTransition>
        <Toaster />
        <Suspense fallback={null}>
          <AvisoSemAcesso />
        </Suspense>
        <LuzNoBotao />
        <MascaraCampos />
        <Confirmador />
      </body>
    </html>
  );
}
